INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(33750025, 'Samsara Dragon', '轮回龙 僧娑罗', '輪廻竜サンサーラ', 'Effect Monster', 'Dragon', 'LIGHT', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：龙族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ②：把墓地的这张卡除外，以自己墓地1只5星以上的龙族怪兽为对象才能发动。那只怪兽加入手卡。那之后，可以把那只怪兽上级召唤。'),
(72237166, 'Samsara Kaiser', '帝王的牲祭', 'カイザー・サクリファイス', 'Effect Monster', 'Warrior', 'EARTH', 2, 200, 100, '这张卡为祭品的祭品召唤成功时，这张卡回到手卡。'),
(5592689, 'Samsara Lotus', '纳祭魔莲', 'サクリファイス・ロータス', 'Effect Monster', 'Plant', 'DARK', 1, NULL, NULL, '自己的结束阶段时这张卡在墓地存在，自己场上没有魔法·陷阱卡存在的场合，可以在自己场上表侧攻击表示特殊召唤。这张卡在场上表侧表示存在的场合，每次自己的准备阶段控制者受到1000分伤害。'),
(29143726, 'Samsara, Dragon of Rebirth', '转生龙', '転生竜サンサーラ', 'Synchro Monster', 'Dragon', 'DARK', 5, 100, 2600, '调整＋调整以外的怪兽1只以上 「转生龙」的效果1回合只能使用1次。 ①：场上的这张卡被对方的效果送去墓地的场合或者被战斗破坏送去墓地的场合，以「转生龙」以外的自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(93124273, 'Samurai Cavalry of Reptier', '雷普提尔的武者骑兵', 'レプティアの武者騎兵', 'Pendulum Effect Monster', 'Dinosaur', 'EARTH', 4, 1800, 1200, '①：这张卡向灵摆怪兽以外的对方的表侧表示怪兽攻击的伤害步骤开始时才能发动。那只怪兽破坏。'),
(40509732, 'Samurai Destroyer', '鬼动武者', '鬼動武者', 'Synchro Monster', 'Machine', 'EARTH', 7, 2600, 1400, '调整＋调整以外的怪兽1只以上 ①：这张卡和对方怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动，只在那次战斗阶段内那只对方怪兽的效果无效化。 ②：表侧表示的这张卡因对方的效果从场上离开的场合，以自己墓地1只机械族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(64926005, 'Samurai of the Ice Barrier', '冰结界的武士', '氷結界の武士', 'Effect Monster', 'Warrior', 'WATER', 4, 1800, 1500, '①：表侧攻击表示的这张卡变成守备表示的场合发动。这张卡破坏，自己抽1张。'),
(68989981, 'Samurai Skull', '堕落武者', '堕ち武者', 'Effect Monster', 'Zombie', 'DARK', 4, 1700, NULL, '①：这张卡召唤成功时才能发动。从卡组把1只不死族怪兽送去墓地。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。从卡组把「堕武者」以外的1只4星以下的不死族怪兽特殊召唤。'),
(14344682, 'Samurai Sword Baron', '侍刀男爵', 'サムライソード・バロン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1200, '1回合1次，选择对方场上守备表示存在的1只怪兽才能发动。选择的怪兽变成表侧攻击表示。'),
(11161666, 'Sanaki the Mikanko Devotee', '御巫奉 纱鸣', '御巫奉サナキ', 'Effect Monster', 'Illusion', 'EARTH', 3, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己场上1张「御巫」卡为对象才能发动。那张卡回到手卡。 ②：这张卡有装备卡被装备的场合才能发动。从卡组把1只幻想魔族以外的「御巫」怪兽特殊召唤。这个回合，自己不是「御巫」怪兽不能从额外卡组特殊召唤。 ③：这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。这张卡当作装备魔法卡使用给那只怪兽装备。'),
(662853, 'Sanctity of Dragon', NULL, NULL, 'Link Monster', 'Dragon', 'LIGHT', NULL, 3000, NULL, NULL),
(50593156, 'Sand Gambler', '沙之赌徒', 'サンド・ギャンブラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 300, 1600, '进行3次投掷硬币。3次都是表的场合，对方场上怪兽全部破坏。3次都是里的场合，自己场上怪兽全部破坏。这个效果1回合只有1次在自己的主要阶段才能使用。'),
(73648243, 'Sand Moth', '沙沼怪', 'サンドモス', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 2000, '里侧守备表示的这张卡被战斗以外的方式破坏送去墓地时，原本的攻击力·守备力交换并在自己场上特殊召唤。'),
(73051941, 'Sand Stone', '沙石怪', 'サンド・ストーン', 'Normal Monster', 'Rock', 'EARTH', 5, 1300, 1600, '从地下突然出现在眼前，用触手做攻击。'),
(33015627, 'Sandaion, the Timelord', '时械神 桑达伊恩', '時械神サンダイオン', 'Effect Monster', 'Fairy', 'LIGHT', 10, 4000, 4000, '这张卡不能从卡组特殊召唤。 ①：「时械神 桑达伊恩」在自己场上只能有1只表侧表示存在。 ②：只有对方场上才有怪兽存在的场合，这张卡可以不用解放作召唤。 ③：这张卡不会被战斗·效果破坏，这张卡的战斗发生的双方的战斗伤害变成0。 ④：这张卡进行战斗的战斗阶段结束时发动。给与对方2000伤害。 ⑤：自己准备阶段发动。这张卡回到持有者卡组。'),
(25955164, 'Sanga of the Thunder', '雷魔神－桑迦', '雷魔神－サンガ', 'Effect Monster', 'Thunder', 'LIGHT', 7, 2600, 2200, '①：只在这张卡在场上表侧表示存在才有1次，这张卡被攻击的伤害计算时，以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击力变成0。'),
(26202165, 'Sangan', '三眼怪', 'クリッター', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合发动。从卡组把1只攻击力1500以下的怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡的效果发动。'),
(55484152, 'Sangen Furo', '灿幻封炉', '燦幻封炉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己的龙族·炎属性怪兽的战斗让怪兽被破坏时，以那1只破坏的怪兽为对象才能发动。那只怪兽在自己场上守备表示特殊召唤。 ②：对方结束阶段，支付1000基本分，以自己墓地1张「灿幻」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡从场上离开的场合除外。'),
(25388971, 'Sangen Kaiho', '灿幻开花', '燦幻開花', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，自己场上的怪兽只有龙族·炎属性怪兽，对方场上的怪兽数量比自己场上的怪兽多的场合才能发动。这次主要阶段结束。 ②：3次以上攻击宣言过的自己·对方回合，把墓地的这张卡除外才能发动。自己抽1张。那之后，可以从手卡把「天杯龙」怪兽任意数量特殊召唤。'),
(66730191, 'Sangen Kaimen', '灿幻开门', '燦幻開門', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡在战斗阶段发动的场合，以下效果各能适用。这张卡在战斗阶段以外发动的场合，从以下效果选1个适用。 ●从卡组把1只4星以下的龙族·炎属性怪兽加入手卡。 ●从手卡把1只龙族·炎属性怪兽特殊召唤。'),
(30336082, 'Sangen Summoning', '杯满之灿幻庄', '盃満ちる燦幻荘', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，自己主要阶段1内，自己场上的龙族·炎属性怪兽不受对方发动的效果影响。 ②：自己主要阶段才能发动。从卡组把1只「天杯龙」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ③：战斗阶段中这张卡被破坏的场合，以自己场上1只龙族同调怪兽为对象才能发动。那只怪兽的攻击力变成2倍。'),
(82570174, 'Sangenpai Bident Dragion', '灿幻升龙 双戟天龙', '燦幻昇龍バイデント・ドラギオン', 'Synchro Tuner Monster', 'Dragon', 'FIRE', 7, 2600, 2000, '龙族调整＋调整以外的龙族怪兽1只以上 这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：这张卡同调召唤的场合，以自己墓地1只龙族·炎属性怪兽为对象才能发动。那只怪兽特殊召唤。这个回合，自己不是龙族怪兽不能特殊召唤。 ②：3次以上攻击宣言过的自己·对方回合才能发动。这张卡从墓地特殊召唤。那之后，可以把场上1张魔法·陷阱卡破坏。'),
(18969888, 'Sangenpai Transcendent Dragion', '灿幻超龙 三极天龙', '燦幻超龍トランセンド・ドラギオン', 'Synchro Monster', 'Dragon', 'FIRE', 10, 3000, 3000, '龙族调整＋调整以外的龙族怪兽1只以上 这个卡名的③的效果在决斗中只能使用1次。 ①：这张卡同调召唤的场合才能发动。场上的怪兽全部变成攻击表示。 ②：只要这张卡在怪兽区域存在，可以攻击的对方怪兽必须作出攻击，对方在战斗阶段中不能把效果发动。 ③：3次以上攻击宣言过的自己·对方回合才能发动。这张卡从墓地特殊召唤。那之后，可以把场上1张卡破坏。'),
(60627999, 'Sanguine Swamp', '血之沼地', '血の沼地', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有这张卡以外的魔法·陷阱卡存在的场合，这张卡破坏。只要这张卡在场上存在，魔法与陷阱卡区域盖放的卡不能发动。第2次的自己的准备阶段时这张卡破坏。'),
(46565218, 'Santa Claws', '撒旦老人', 'サタンクロース', 'Effect Monster', 'Fiend', 'LIGHT', 6, 1200, 2500, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上守备表示特殊召唤。 ②：这张卡用这张卡的①的方法特殊召唤的回合的结束阶段才能发动。自己抽1张。'),
(53539634, 'Sanwitch', '三眼巫', 'クリッチー', 'Fusion Monster', 'Spellcaster', 'DARK', 6, 2100, 1800, '「三眼怪」＋「黑森林的魔女」'),
(17639150, 'Saqlifice', '机壳的牲祭', '機殻の生贄', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「机壳」怪兽才能装备。 ①：装备怪兽的攻击力上升300，不会被战斗破坏。 ②：「机壳」怪兽上级召唤的场合，装备怪兽可以作为2只的数量解放。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1只「机壳」怪兽加入手卡。'),
(37511832, 'Sargasso Lighthouse', '死域海的灯塔', 'サルガッソの灯台', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '给与自己伤害的魔法卡的效果发动时才能发动。那个效果让自己受到的效果伤害变成0。此外，只要这张卡在墓地存在，「异次元的古战场-死域海」的效果让自己受到的效果伤害变成0。盖放的这张卡被送去墓地时，可以从卡组把1张「异次元的古战场-死域海」加入手卡。'),
(1127737, 'Sargasso the D.D. Battlefield', '异次元的古战场-死域海', '異次元の古戦場－サルガッソ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '每次超量召唤成功，那个玩家受到500分伤害。此外，控制超量怪兽的玩家各自在每次自己的结束阶段受到500分伤害。'),
(99801464, 'Sari of the Silverwing Axe', '银翼之斧式配饰-莎莉', '銀翼のAXE－サリー', 'Effect Monster', 'Machine', 'LIGHT', 3, 500, 100, '这个卡名的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力·守备力上升100的装备卡使用给那只怪兽装备。这个效果在对方回合也能发动。'),
(74997493, 'Saryuja Skull Dread', '锁龙蛇－骷髅四尸', '鎖龍蛇－スカルデット', 'Link Monster', 'Dragon', 'EARTH', NULL, 2800, NULL, '卡名不同的怪兽2只以上 ①：这张卡得到作为这张卡的连接素材的怪兽数量的以下效果。 ●2只以上：这张卡所连接区有怪兽召唤·特殊召唤的场合发动。那些怪兽的攻击力·守备力上升300。 ●3只以上：1回合1次，自己主要阶段才能发动。从手卡把1只怪兽特殊召唤。 ●4只：这张卡连接召唤时才能发动。自己抽4张。那之后，选自己3张手卡用喜欢的顺序回到卡组下面。'),
(11434258, 'Saryuja''s Shackles', '蛇龙的枷锁', '蛇龍の枷鎖', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方的场上·墓地1只连接怪兽为对象才能发动。自己从卡组抽出那只怪兽的连接标记的数量。那之后，自己手卡是2张以上的场合，选那之内的2张用喜欢的顺序回到卡组最下面。'),
(16222645, 'Sasuke Samurai', '一刀两断侍', '一刀両断侍', 'Effect Monster', 'Warrior', 'WIND', 2, 500, 800, '这张卡攻击里侧守备表示的怪兽的场合，不进行伤害计算，里侧守备表示的怪兽以本来的里侧守备形式直接破坏。'),
(11760174, 'Sasuke Samurai #2', '言语道断侍', '言語道断侍', 'Effect Monster', 'Warrior', 'WIND', 1, 200, 300, '支付800基本分。到本回合结束阶段为止，所有的魔法·陷阱卡都不能发动。'),
(77379481, 'Sasuke Samurai #3', '大盘振舞侍', '大盤振舞侍', 'Effect Monster', 'Warrior', 'LIGHT', 3, 1000, 1000, '这张卡给与对方战斗伤害时，对方玩家将手卡抽到7张为止。'),
(64538655, 'Sasuke Samurai #4', '一击必杀侍', '一撃必殺侍', 'Effect Monster', 'Warrior', 'WIND', 4, 1200, 1200, '①：这张卡和对方怪兽进行战斗的伤害步骤开始时发动。进行1次投掷硬币，对里表作猜测。猜中的场合，那只对方怪兽破坏。'),
(65056481, 'Satellarknight Alsahm', '卫星骑士 天箭夏姆', '星因士 シャム', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1400, 1800, '「星因士 左旗一」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。给与对方1000伤害。'),
(2273734, 'Satellarknight Altair', '卫星骑士 天鹰阿尔泰尔', '星因士 アルタイル', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1300, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合，以「星因士 河鼓二」以外的自己墓地1只「星骑士」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时「星骑士」怪兽以外的自己怪兽不能攻击。'),
(26057276, 'Satellarknight Betelgeuse', '卫星骑士 猎户贝忒基乌斯', '星因士 ベテルギウス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 700, 1900, '「星因士 参宿四」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合，以「星因士 参宿四」以外的自己墓地1张「星骑士」卡为对象才能发动。这张卡送去墓地，作为对象的卡加入手卡。'),
(86466163, 'Satellarknight Capella', '卫星骑士 御夫卡培拉', '星因士 カペラ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1100, 2000, '「星因士 五车二」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。这个回合自己在用怪兽3只以上为素材的超量召唤的场合，可以把自己场上的4星以下的「星骑士」怪兽当作5星的素材使用。'),
(75878039, 'Satellarknight Deneb', '卫星骑士 天鹅德奈普', '星因士 デネブ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把「星因士 天津四」以外的1只「星骑士」怪兽加入手卡。'),
(99668578, 'Satellarknight Procyon', '卫星骑士 小犬普罗席翁', '星因士 プロキオン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1300, 1200, '「星因士 南河三」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。手卡1只「星骑士」怪兽送去墓地，自己从卡组抽1张。'),
(13851202, 'Satellarknight Rigel', '卫星骑士 猎户里格尔', '星因士 リゲル', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 700, '「星因士 参宿七」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合，以场上1只「星骑士」怪兽为对象才能发动。那只怪兽攻击力上升500，结束阶段送去墓地。'),
(63274863, 'Satellarknight Sirius', '卫星骑士 大犬西利乌斯', '星因士 シリウス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 900, '「星因士 天狼星」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合，以自己墓地5只「星骑士」怪兽为对象才能发动。那5只怪兽回到卡组洗切。那之后，自己从卡组抽1张。'),
(18205590, 'Satellarknight Skybridge', '架天桥的卫星骑士', '天架ける星因士', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「星骑士」怪兽为对象才能发动。和那只怪兽卡名不同的1只「星骑士」怪兽从卡组特殊召唤，作为对象的怪兽回到卡组。只要这个效果特殊召唤的怪兽在场上表侧表示存在，自己不是「星骑士」怪兽不能特殊召唤。'),
(1050186, 'Satellarknight Unukalhai', '卫星骑士 巨蛇乌努克', '星因士 ウヌク', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1000, '「星因士 天市右垣七」的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从卡组把「星因士 天市右垣七」以外的1张「星骑士」卡送去墓地。'),
(38667773, 'Satellarknight Vega', '卫星骑士 天琴维嘉', '星因士 ベガ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1200, 1600, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从手卡把「星因士 织女一」以外的1只「星骑士」怪兽特殊召唤。'),
(96223501, 'Satellarknight Zefrathuban', '光卫星骑士－源质图邦', '竜星因士－セフィラツバーン', 'Pendulum Effect Monster', 'Warrior', 'LIGHT', 4, NULL, 2100, '「龙星因士-神数右枢」的怪兽效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·灵摆召唤成功的场合，以这张卡以外的自己的怪兽区域·灵摆区域1张「星骑士」卡或者「神数」卡和对方场上1张表侧表示的卡为对象才能发动。那些卡破坏。'),
(50400231, 'Satellite Cannon', '卫星加农炮', 'サテライト・キャノン', 'Effect Monster', 'Machine', 'LIGHT', 5, NULL, NULL, '这张卡不会被7星以下的怪兽战斗破坏。每次的自己的结束阶段，这张卡的攻击力上升1000。这张卡进行攻击的场合，用这个效果上升的攻击力在伤害计算后回到0。'),
(57458399, 'Satellite Synchron', '卫星同步士', 'サテライト・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 2, 700, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地有怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：原本卡名包含「战士」、「同调士」、「星尘」之内任意种的同调怪兽在自己的场上或墓地存在的场合才能发动。这张卡的等级直到回合结束时变成4星。'),
(84664085, 'Satellite Warrior', '卫星战士', 'サテライト・ウォリアー', 'Synchro Monster', 'Warrior', 'DARK', 10, 2500, 2000, '调整＋调整以外的同调怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以最多有自己墓地的同调怪兽数量的对方场上的卡为对象才能发动。那些卡破坏，这张卡的攻击力上升破坏数量×1000。 ②：同调召唤的这张卡被破坏的场合才能发动。8星以下的「战士」、「同调士」、「星尘」同调怪兽合计最多3只从自己墓地特殊召唤（同名卡最多1张）。'),
(85032782, 'Sauge de Fleur', '鲜花之贤者', '時花の賢者－フルール・ド・サージュ', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2900, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只怪兽和场上1张卡为对象才能发动。这张卡从手卡特殊召唤，作为对象的卡破坏。 ②：这张卡从场上送去墓地的场合，以这张卡以外的自己墓地1只怪兽为对象才能发动。那只怪兽回到卡组。那之后，从自己的卡组·墓地选1只植物族·1星怪兽加入手卡。'),
(88284599, 'Sauravis, Dragon Sage of the Voiceless Voice', '肃声之龙贤圣 萨拉维思', '粛声の竜賢聖サウラヴィス', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2600, 2800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从自己的手卡·墓地让包含仪式魔法卡的2张魔法卡回到卡组，从手卡特殊召唤。 ②：对方把卡的效果发动时，让场上的这张卡回到手卡才能发动。从手卡·卡组把1只战士族·龙族而光属性的仪式怪兽特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段回到卡组。'),
(4810828, 'Sauravis, the Ancient and Ascended', '古圣戴 萨拉维思', '古聖戴サウラヴィス', 'Ritual Effect Monster', 'Dragon', 'LIGHT', 7, 2600, 2800, '「精灵的祝福」降临 ①：自己场上的怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡从手卡丢弃才能发动。那个发动无效。 ②：对方把怪兽特殊召唤之际，让场上的这张卡回到手卡才能发动。那次特殊召唤无效，那些怪兽除外。'),
(41753322, 'Sauropod Brachion', '龙脚兽 腕龙', '竜脚獣ブラキオン', 'Effect Monster', 'Dinosaur', 'EARTH', 8, 1500, 3000, '这张卡不能从卡组特殊召唤。这张卡可以把1只恐龙族怪兽解放表侧表示上级召唤。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转召唤成功的场合发动。这张卡以外的场上的怪兽全部变成里侧守备表示。 ③：这张卡被攻击的场合，那次战斗发生的对对方的战斗伤害变成2倍。'),
(32391631, 'Savage Colosseum', '野蛮斗技场', 'サベージ・コロシアム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上存在的怪兽进行攻击的场合，那只怪兽的控制者在伤害步骤结束时回复300基本分。只要这张卡在场上存在，可以攻击的怪兽必须作出攻击。结束阶段时，回合玩家的场上表侧攻击表示存在的没有攻击宣言的怪兽全部破坏。'),
(75198893, 'Scanner', '扫描机器人', 'スキヤナー', 'Effect Monster', 'Machine', 'LIGHT', 1, -1, -1, '选择从游戏中除外的1只对方怪兽发动。这张卡直到结束阶段时当作和选择怪兽同名卡使用，变成和选择怪兽相同属性·等级·攻击力·守备力。这个效果1回合只能使用1次。这个效果适用的这张卡从场上离开的场合，从游戏中除外。'),
(67284107, 'Scapeghost', '替罪鬼羊', 'スケープ・ゴースト', 'Tuner Monster', 'Zombie', 'DARK', 1, NULL, NULL, '①：这张卡反转的场合才能发动。在自己场上把「黑羊衍生物」（不死族·暗·1星·攻/守0）任意数量特殊召唤。'),
(73915051, 'Scapegoat', '替罪山羊', 'スケープ・ゴート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·反转召唤·特殊召唤。 ①：在自己场上把4只「羊衍生物」（兽族·地·1星·攻/守0）守备表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(1855886, 'Scar of the Vendread', '伤痕・仇尸', 'スカー・ヴェンデット', 'Effect Monster', 'Zombie', 'DARK', 6, 2300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合才能发动。从卡组把1张「复仇死者」魔法·陷阱卡加入手卡。 ②：这张卡在墓地存在的状态，场上的怪兽被解放的场合，从自己墓地把这张卡以外的1只不死族怪兽除外才能发动。这张卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是「复仇死者」怪兽不能特殊召唤。'),
(46877100, 'Scareclaw Acro', '恐惧爪・高空阿克罗亚', 'スケアクロー・アクロア', 'Effect Monster', 'Beast', 'EARTH', 3, NULL, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以从手卡往自己场上的「恐吓爪牙族」怪兽的相邻的或者相同纵列的自己的主要怪兽区域特殊召唤。 ②：只要这张卡在怪兽区域存在，额外怪兽区域的自己的「恐吓爪牙族」怪兽的攻击力上升自己场上的守备表示怪兽数量×300。'),
(5941982, 'Scareclaw Alternative', '恐惧爪・继承', '肆世壊の継承', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把自己场上3只「恐吓爪牙族」怪兽解放才能发动。这个回合，对方不用守备表示不能把怪兽特殊召唤。 ②：自己回合，把墓地的这张卡除外才能发动。给与对方为场上的守备表示怪兽数量×100伤害。'),
(83558891, 'Scareclaw Arrival', '恐惧爪・新星', '肆世壊の新星', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己墓地1只「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」为对象才能发动。那只怪兽守备表示特殊召唤。 ②：自己场上的「恐吓爪牙族」连接怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(83488497, 'Scareclaw Astra', '恐惧爪・雷电阿斯特拉', 'スケアクロー・アストラ', 'Effect Monster', 'Beast', 'EARTH', 3, NULL, 1300, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以从手卡往自己场上的「恐吓爪牙族」怪兽的相邻的或者相同纵列的自己的主要怪兽区域特殊召唤。 ②：只要自己场上有守备表示的「恐吓爪牙族」怪兽存在，额外怪兽区域的自己的「恐吓爪牙族」怪兽在同1次的战斗阶段中可以作出最多有那个种类数量的攻击。'),
(19882096, 'Scareclaw Belone', '恐惧爪・针尖贝罗尼亚', 'スケアクロー・ベロネア', 'Effect Monster', 'Beast', 'EARTH', 3, NULL, 1700, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以从手卡往自己场上的「恐吓爪牙族」怪兽的相邻的或者相同纵列的自己的主要怪兽区域特殊召唤。 ②：只要这张卡在怪兽区域存在，额外怪兽区域的自己的「恐吓爪牙族」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(32152870, 'Scareclaw Decline', '恐惧爪・肆世坏的械贬', '械貶する肆世壊', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己的场上·墓地1张「肆世坏-恐惧世界」为对象才能发动。那张卡回到持有者手卡。自己场上有「维萨斯-斯塔弗罗斯特」存在的场合，可以再选对方场上1只表侧表示怪兽变成里侧守备表示。 ②：场上有守备表示怪兽3只以上存在的场合，把墓地的这张卡除外才能发动。从自己墓地选1张「恐吓爪牙族」卡加入手卡。'),
(7236721, 'Scareclaw Defanging', '恐惧爪・被界放的肆世坏', '界放せし肆世壊', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的「恐吓爪牙族」连接怪兽以及「维萨斯-斯塔弗罗斯特」不会成为对方的效果的对象，不会被对方的效果破坏。 ②：自己的「恐吓爪牙族」连接怪兽或者「维萨斯-斯塔弗罗斯特」战斗破坏的怪兽不去墓地而除外。 ③：从自己的场上·墓地把1只「恐吓爪牙族」连接怪兽除外，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(78534861, 'Scareclaw Kashtira', '恐惧爪・怒刹帝利', 'スケアクロー・クシャトリラ', 'Effect Monster', 'Psychic', 'EARTH', 7, NULL, 2600, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤，从自己的手卡·墓地选1张「俱舍怒威族」卡或者「恐吓爪牙族」卡除外。 ②：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ③：自己的「俱舍怒威族」怪兽或者「恐吓爪牙族」怪兽和对方怪兽进行战斗的场合，直到回合结束时那只对方怪兽的效果无效化。'),
(53776969, 'Scareclaw Light-Heart', '恐惧爪・赖特哈忒', 'スケアクロー・ライトハート', 'Link Monster', 'Beast-Warrior', 'DARK', NULL, 500, NULL, '「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」1只 这张卡连接召唤的场合，若非自己的主要怪兽区域的怪兽则不能作为连接素材。这个卡名的②的效果在决斗中只能使用1次。 ①：这张卡在额外怪兽区域连接召唤的场合才能发动。从卡组把1张「肆世坏-恐惧世界」加入手卡。 ②：自己场上有「维萨斯-斯塔弗罗斯特」存在的场合才能发动。这张卡从墓地特殊召唤。'),
(82361809, 'Scareclaw Reichheart', '恐惧爪・赖希哈忒', 'スケアクロー・ライヒハート', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, 2100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往自己场上的「恐吓爪牙族」怪兽的相邻的或者相同纵列的自己的主要怪兽区域特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「恐吓爪牙族」魔法·陷阱卡加入手卡。场上有守备表示怪兽3只以上存在的场合，再让自己可以从卡组抽1张。'),
(79552283, 'Scareclaw Sclash', '恐惧爪・牙掌突', '肆世壊の牙掌突', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以自己场上1只「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」为对象才能发动。这个回合，那只怪兽可以用表侧守备表示的状态作出攻击。那个场合，攻击力和守备力之内较高方的数值适用进行伤害计算。 ②：额外怪兽区域有自己的「恐吓爪牙族」怪兽存在，对方把效果发动时，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。那个效果无效。'),
(41619242, 'Scareclaw Straddle', '恐惧爪・从肆世坏的跨天', '肆世壊からの天跨', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●以自己场上1只「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」和对方场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的攻击力·守备力上升那只对方怪兽的攻击力和守备力之内较高方的数值。 ●自己场上的「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」为对象的效果发动时才能发动。那个效果无效。'),
(59120809, 'Scareclaw Tri-Heart', '恐惧爪・特赖希哈忒', 'スケアクロー・トライヒハート', 'Link Monster', 'Beast-Warrior', 'DARK', NULL, 3000, NULL, '效果怪兽3只 这张卡不用连接召唤不能特殊召唤。 ①：场上的表侧表示怪兽变成守备表示。 ②：场上的这张卡不受守备表示怪兽发动的效果影响。 ③：1回合1次，这张卡在额外怪兽区域存在的场合，以自己墓地1只3星「恐吓爪牙族」怪兽为对象才能发动。那只怪兽特殊召唤，从卡组把1只「恐吓爪牙族」怪兽加入手卡。这个效果发动过的回合，自己不是「恐吓爪牙族」怪兽不能特殊召唤。'),
(95245571, 'Scareclaw Twinsaw', '恐惧爪・双牙', '肆世壊の双牙', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只「恐吓爪牙族」怪兽解放，以对方场上2张卡为对象才能发动。那些卡破坏。自己场上有「维萨斯-斯塔弗罗斯特」存在的场合，这个效果破坏的卡不去墓地而除外。 ②：场上有连接3以上的怪兽存在的场合，把墓地的这张卡除外才能发动。这个回合，场上的连接怪兽不能把效果发动。'),
(50215517, 'Scarlet Security', '深红狱防术', 'クリムゾン・ヘル・セキュア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「红莲魔龙」表侧表示存在的场合才能发动。对方场上存在的魔法·陷阱卡全部破坏。'),
(80666118, 'Scarlight Red Dragon Archfiend', '暗红恶魔龙・荣光右痕', 'レッド・デーモンズ・ドラゴン・スカーライト', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, '调整＋调整以外的怪兽1只以上 ①：这张卡的卡名只要在场上·墓地存在当作「红莲魔龙」使用。 ②：1回合1次，自己主要阶段才能发动。这张卡以外的持有这张卡的攻击力以下的攻击力的特殊召唤的效果怪兽全部破坏。那之后，给与对方这个效果破坏的怪兽数量×500伤害。'),
(84764038, 'Scarm, Malebranche of the Burning Abyss', '彼岸恶鬼 司加密林', '彼岸の悪鬼 スカラマリオン', 'Effect Monster', 'Fiend', 'DARK', 3, 800, 2000, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把「彼岸的恶鬼 斯卡尔米利奥内」以外的1只恶魔族·暗属性·3星怪兽加入手卡。'),
(5498296, 'Scarr, Scout of Dark World', '暗黑界的斥候 斯卡', '暗黒界の斥候 スカー', 'Effect Monster', 'Fiend', 'DARK', 2, 500, 500, '①：这张卡被战斗破坏送去墓地的场合发动。从卡组把1只4星以下的「暗黑界」怪兽加入手卡。'),
(87451661, 'Scarred Dragon Archfiend', '绯暗红恶魔', 'スカーレッド・デーモン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, '调整＋调整以外的暗属性怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「红莲魔龙」使用。 ②：这张卡从怪兽区域送去墓地的场合才能发动。从额外卡组把1只「红莲魔龙」当作同调召唤作特殊召唤。这张卡作为龙族·暗属性同调怪兽的同调素材送去墓地的场合，可以再把对方场上的攻击表示怪兽全部破坏。'),
(45298492, 'Scarred Warrior', '伤痕战士', 'スカー・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 5, 2100, 1000, '调整＋调整以外的怪兽1只以上 只要这张卡在场上表侧表示存在，对方不能选择表侧表示存在的其他的战士族怪兽作为攻击对象。此外，这张卡1回合只有1次不会被战斗破坏。'),
(68087897, 'Scary Moth', '鳞粉蛾', 'スケイルモース', 'Effect Monster', 'Insect', 'WIND', 6, 1800, 2300, '只要这张卡场上表侧表示存在，双方玩家1回合只能1次把怪兽特殊召唤。'),
(40597694, 'Scatter Fusion', '散射结合', 'スキャッター・フュージョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方场上有怪兽存在的场合才能发动。岩石族以外的「宝石骑士」融合怪兽卡决定的融合素材怪兽从自己卡组送去墓地，把那1只融合怪兽从额外卡组融合召唤。这张卡从场上离开时那只怪兽破坏。这个效果的发动后，直到回合结束时自己不是「宝石骑士」怪兽不能从额外卡组特殊召唤。'),
(57594700, 'Schuberta the Melodious Maestra', '幻奏音姬 巨匠舒伯特', '幻奏の音姫マイスタリン・シューベルト', 'Fusion Monster', 'Fairy', 'LIGHT', 6, 2400, 2000, '「幻奏」怪兽×2 ①：只在这张卡在场上表侧表示存在才有1次，以双方墓地的卡合计最多3张为对象才能发动。那些卡除外。这张卡的攻击力上升这个效果除外的卡数量×200。这个效果在对方回合也能发动。'),
(18294799, 'Schwarzschild Infinity Dragon', '无限龙 史瓦西', '無限竜シュヴァルツシルト', 'Effect Monster', 'Dragon', 'DARK', 8, 2000, NULL, '这个卡名的效果1回合只能使用1次，这个效果发动的回合，自己不是龙族超量怪兽不能从额外卡组特殊召唤。 ①：自己场上没有怪兽存在的场合或者对方场上有攻击力2000以上的怪兽存在的场合才能发动。这张卡从手卡特殊召唤，从卡组把「无限龙 施瓦西龙」以外的1只光·暗属性的龙族·8星怪兽守备表示特殊召唤。这个效果从卡组特殊召唤的怪兽的效果无效化。'),
(6930746, 'Schwarzschild Limit Dragon', '限界龙 施瓦西龙', '限界竜シュヴァルツシルト', 'Effect Monster', 'Dragon', 'DARK', 8, 2000, NULL, '①：对方场上有攻击力2000以上的怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(67532912, 'Science Soldier', '科学特殊兵', '科学特殊兵', 'Normal Monster', 'Warrior', 'DARK', 3, 800, 800, '为对抗未知生物，装备着最新科学武器的士兵。背后的集装箱里藏着各种各样的兵器。'),
(41767843, 'Score the Melodious Diva', '幻奏音女 丝可娅', '幻奏の音女スコア', 'Effect Monster', 'Fairy', 'LIGHT', 2, 200, 200, '①：自己的「幻奏」怪兽和对方怪兽进行战斗的伤害计算时，把这张卡从手卡送去墓地才能发动。那只对方怪兽的攻击力·守备力直到回合结束时变成0。'),
(93723936, 'Scourge of the White Forest', '白森之魔', '白き森のあくま', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只同调怪兽解放，以场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。把「白森林」同调怪兽解放发动的场合，可以再从自己墓地把1只幻想魔族怪兽特殊召唤。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(75078585, 'Scramble Egg', '破蛋', 'スクランブル・エッグ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽被战斗·效果破坏送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「小走鹃」特殊召唤。'),
(83054225, 'Scramble!! Scramble!!', '紧急起飞', '緊急発進', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '对方场上的怪兽数量比衍生物以外的自己场上的怪兽数量多的场合，把自己场上的「幻兽机衍生物」任意数量解放才能发动。把解放的衍生物数量的名字带有「幻兽机」的怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段时回到持有者卡组。「紧急起飞」在1回合只能发动1张。'),
(45815891, 'Scrap Archfiend', '废铁死亡恶魔', 'スクラップ・デスデーモン', 'Synchro Monster', 'Fiend', 'EARTH', 7, 2700, 1800, '调整＋调整以外的怪兽1只以上'),
(19139516, 'Scrap Beast', '废铁野兽', 'スクラップ・ビースト', 'Tuner Monster', 'Beast', 'EARTH', 4, 1600, 1300, '场上表侧守备表示存在的这张卡被选择作为攻击对象的场合，战斗阶段结束时这张卡破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以选择「废铁兽」以外的自己墓地存在的1只名字带有「废铁」的怪兽加入手卡。'),
(51555725, 'Scrap Breaker', '废铁破坏者', 'スクラップ・ブレイカー', 'Effect Monster', 'Machine', 'EARTH', 6, 2100, 700, '对方场上存在怪兽的场合，这张卡可以从手卡特殊召唤。用这个方法把这张卡特殊召唤成功时，选择自己场上表侧表示存在的1只名字带有「废铁」的怪兽破坏。'),
(56746202, 'Scrap Chimera', '废铁客迈拉', 'スクラップ・キマイラ', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 500, '把这张卡作为同调素材的场合，不是「废铁」怪兽的同调召唤不能使用，其他的同调素材怪兽必须全部是「废铁」怪兽。 ①：这张卡召唤成功时，以自己墓地1只「废铁」调整为对象才能发动。那只怪兽特殊召唤。'),
(5577649, 'Scrap Crash', '废铁粉碎', 'スクラップ・クラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「废铁」的怪兽被破坏送去墓地时才能发动。场上表侧表示存在的魔法·陷阱卡全部破坏。'),
(76774528, 'Scrap Dragon', '废铁龙', 'スクラップ・ドラゴン', 'Synchro Monster', 'Dragon', 'EARTH', 8, 2800, 2000, '调整＋调整以外的怪兽1只以上 ①：1回合1次，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。 ②：这张卡被对方破坏送去墓地的场合，以同调怪兽以外的自己墓地1只「废铁」怪兽为对象发动。那只怪兽特殊召唤。'),
(28388296, 'Scrap Factory', '废铁工厂', 'スクラップ・ファクトリー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：场上的「废铁」怪兽的攻击力·守备力上升200。 ②：场上的表侧表示的「废铁」怪兽被效果破坏送去墓地时才能发动。自己从卡组把1只「废铁」怪兽特殊召唤。'),
(8529136, 'Scrap Fist', '废铁拳', 'スクラップ・フィスト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「废品战士」为对象才能发动。这个回合，那只自己怪兽和对方怪兽进行战斗的场合，以下效果适用。 ●对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ●作为对象的怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ●对方受到的战斗伤害变成2倍。 ●作为对象的怪兽不会被战斗破坏。 ●进行战斗的对方怪兽在伤害步骤结束时破坏。'),
(91019775, 'Scrap Garage', '废铁车库', 'スクラップ・ガレージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的机械族怪兽被战斗·效果破坏的场合，以自己墓地最多3只机械族·暗属性怪兽为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0。 ②：把墓地的这张卡除外，以自己场上1只机械族怪兽为对象才能发动。那只怪兽破坏。'),
(83135907, 'Scrap Goblin', '废铁格布林', 'スクラップ・ゴブリン', 'Tuner Monster', 'Beast-Warrior', 'EARTH', 3, NULL, 500, '场上表侧守备表示存在的这张卡被选择作为攻击对象的场合，战斗阶段结束时这张卡破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以选择「废铁哥布林」以外的自己墓地存在的1只名字带有「废铁」的怪兽加入手卡。此外，这张卡不会被战斗破坏。'),
(82012319, 'Scrap Golem', '废铁魔像', 'スクラップ・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 5, 2300, 1400, '1回合1次，可以选择自己墓地存在的1只4星以下的名字带有「废铁」的怪兽在自己或者对方场上特殊召唤。'),
(55624610, 'Scrap Hunter', '废铁猎人', 'スクラップ・ハンター', 'Effect Monster', 'Machine', 'EARTH', 3, 1600, 400, '1回合1次，可以选择这张卡以外的自己场上表侧表示存在的1只名字带有「废铁」的怪兽破坏，从自己卡组把1只调整送去墓地。'),
(97000273, 'Scrap Kong', '废铁金刚', 'スクラップ・コング', 'Effect Monster', 'Beast', 'EARTH', 4, 2000, 1000, '这张卡召唤成功时，这张卡破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以选择「废铁金刚」以外的自己墓地存在的1只名字带有「废铁」的怪兽加入手卡。'),
(22539270, 'Scrap Lube', '废铁油带', 'スクラップ・オイルゾーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只名字带有「废铁」的怪兽发动。选择的怪兽从墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这张卡不在场上存在时，那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。这张卡发动的回合，自己不能进行战斗阶段。'),
(67038874, 'Scrap Mind Reader', '废铁读心者', 'スクラップ・マインドリーダー', 'Tuner Monster', 'Machine', 'EARTH', 1, NULL, NULL, '这张卡在墓地存在的场合，自己的主要阶段2才能发动1次。选择「废铁读心者」以外的自己场上表侧表示存在的1只名字带有「废铁」的怪兽破坏，这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。把这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是名字带有「废铁」的怪兽。'),
(64550682, 'Scrap Orthros', '废铁俄耳托斯', 'スクラップ・オルトロス', 'Tuner Monster', 'Beast', 'EARTH', 4, 1700, 1100, '这张卡不能通常召唤。自己场上有「废铁」怪兽存在的场合可以特殊召唤。 ①：这个方法让这张卡特殊召唤成功的场合，以自己场上1只「废铁」怪兽为对象发动。那只自己的「废铁」怪兽破坏。 ②：这张卡被「废铁」卡的效果破坏送去墓地的场合，以「废铁双头犬」以外的自己墓地1只「废铁」怪兽为对象才能发动。那只怪兽加入手卡。'),
(59699355, 'Scrap Rage', '废铁反击', 'スクラップ・カウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上守备表示存在的名字带有「废铁」的怪兽被攻击的场合，那次伤害计算时才能发动。被攻击的名字带有「废铁」的怪兽的守备力上升2000，战斗阶段结束时破坏。'),
(80529459, 'Scrap Raptor', '废铁盗龙', 'スクラップ・ラプター', 'Tuner Monster', 'Dinosaur', 'EARTH', 4, 1400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只怪兽为对象才能发动。那只怪兽破坏。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「废铁」怪兽召唤。 ②：这张卡被「废铁」卡的效果破坏送去墓地的场合才能发动。从卡组把1张「废铁工厂」或者1只调整以外的「废铁」怪兽加入手卡。'),
(4334811, 'Scrap Recycler', '废铁回收机', 'スクラップ・リサイクラー', 'Effect Monster', 'Machine', 'EARTH', 3, 900, 1200, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1只机械族怪兽送去墓地。 ②：1回合1次，让自己墓地2只机械族·地属性·4星怪兽回到卡组才能发动。自己从卡组抽1张。'),
(92901944, 'Scrap Searcher', '废铁探寻者', 'スクラップ・サーチャー', 'Effect Monster', 'Winged Beast', 'EARTH', 1, 100, 300, '这张卡在墓地存在，自己场上存在的「废铁搜索鸟」以外的名字带有「废铁」的怪兽被破坏送去墓地时，这张卡可以从墓地特殊召唤。这张卡特殊召唤成功时，名字带有「废铁」的怪兽以外的自己场上表侧表示存在的怪兽全部破坏。'),
(69155991, 'Scrap Shark', '废铁鲨', 'スクラップ・シャーク', 'Effect Monster', 'Fish', 'EARTH', 4, 2100, NULL, '效果怪兽的效果·魔法·陷阱卡发动时，场上表侧表示存在的这张卡破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以从自己卡组把1只名字带有「废铁」的怪兽送去墓地。'),
(74439492, 'Scrap Sheen', '废铁抛光', 'スクラップ・ポリッシュ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「废铁」的怪兽破坏。自己场上表侧表示存在的全部名字带有「废铁」的怪兽的攻击力直到这个回合的结束阶段时上升1000。'),
(65503206, 'Scrap Soldier', '废铁士兵', 'スクラップ・ソルジャー', 'Tuner Monster', 'Warrior', 'EARTH', 5, 2100, 700, '场上表侧守备表示存在的这张卡被选择作为攻击对象的场合，战斗阶段结束时这张卡破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以选择「废铁士兵」以外的自己墓地存在的1只名字带有「废铁」的怪兽加入手卡。把这张卡作为同调素材的场合，不是名字带有「废铁」的怪兽的同调召唤不能使用。'),
(16449363, 'Scrap Synchron', '废铁同步士', 'スクラップ・シンクロン', 'Tuner Monster', 'Machine', 'EARTH', 1, 700, 100, '这张卡可以作为「同调士」调整的代替而成为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：以「同调士」调整为素材的同调怪兽同调召唤的场合，手卡的这张卡也能作为同调素材。 ②：自己场上的以下怪兽被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。 ●有「废品战士」的卡名记述的怪兽 ●原本卡名包含「战士」的同调怪兽'),
(50278554, 'Scrap Twin Dragon', '废铁双头龙', 'スクラップ・ツイン・ドラゴン', 'Synchro Monster', 'Dragon', 'EARTH', 9, 3000, 2200, '名字带有「废铁」的调整＋调整以外的怪兽1只以上 1回合1次，选择自己场上存在的1张卡和对方场上存在的2张卡才能发动。选择的自己的卡破坏，选择的对方的卡回到手卡。这张卡被对方破坏送去墓地时，选择同调怪兽以外的自己墓地存在的1只名字带有「废铁」的怪兽特殊召唤。'),
(42711820, 'Scrap Warrior', '废铁战士', 'スクラップ・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 3, 1700, 100, '「废铁同调士」＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组选1只「废品同调士」或者1张有「废品战士」的卡名记述的卡加入手卡或送去墓地。 ②：「废铁战士」以外的自己场上的以下怪兽发动的效果不会被无效化。 ●有「废品战士」的卡名记述的怪兽 ●原本卡名包含「战士」的同调怪兽'),
(32761286, 'Scrap Worm', '废铁异虫', 'スクラップ・ワーム', 'Tuner Monster', 'Insect', 'EARTH', 2, 500, 100, '这张卡可以直接攻击对方玩家。这张卡攻击的场合，战斗阶段结束时破坏。这张卡被名字带有「废铁」的卡的效果破坏送去墓地的场合，可以选择「废铁蠕虫」以外的自己墓地存在的1只名字带有「废铁」的怪兽加入手卡。'),
(47363932, 'Scrap Wyvern', '废铁翼龙', 'スクラップ・ワイバーン', 'Link Monster', 'Dragon', 'EARTH', NULL, 1700, NULL, '包含「废铁」怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「废铁」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，选自己场上1张卡破坏。 ②：这张卡已在怪兽区域存在的状态，场上的表侧表示的「废铁」怪兽被效果破坏的场合才能发动。从卡组把1只「废铁」怪兽特殊召唤。那之后，选场上1张卡破坏。'),
(85520170, 'Scrap-Iron Sacred Statue', '铁屑神像', 'くず鉄の神像', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己的墓地·除外状态的1只7·8星的龙族同调怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到额外卡组。发动后这张卡不送去墓地，直接盖放。 ②：盖放的这张卡被对方的效果破坏的场合才能发动。从额外卡组把1只「红龙」特殊召唤。'),
(98427577, 'Scrap-Iron Scarecrow', '铁屑稻草人', 'くず鉄のかかし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。那次攻击无效。发动后这张卡不送去墓地，直接盖放。'),
(50947142, 'Scrap-Iron Signal', '铁屑信号', 'くず鉄のシグナル', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：需要同调怪兽作为素材的同调怪兽在自己场上存在，对方把怪兽的效果发动时才能发动。那个发动无效。发动后这张卡不送去墓地，直接盖放。'),
(48497555, 'Scrap-Iron Statue', '铁屑像', 'くず鉄の像', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「废铁像」的①②的效果1回合各能使用1次。 ①：对方场上的已是表侧表示存在的魔法·陷阱卡把那个效果发动时才能发动。那张卡破坏。发动后这张卡不送去墓地，直接盖放。 ②：这张卡被送去墓地的场合，以自己墓地1只「废品」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(48445393, 'Scrapstorm', '废铁骤雨', 'スクラップ・スコール', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「废铁」的怪兽发动。从自己卡组把1只名字带有「废铁」的怪兽送去墓地，抽1张卡。那之后，选择的怪兽破坏。'),
(1050684, 'Scrapyard', '废铁区域', 'スクラップ・エリア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「废铁」调整加入手卡。'),
(67100549, 'Screams of the Branded', '烙印凶鸣', '烙印凶鳴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：融合怪兽被送去自己墓地的回合才能发动。自己的墓地·除外状态的1只融合怪兽特殊召唤。 ②：这张卡为让「阿不思的落胤」的效果发动而被送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。'),
(10352095, 'Scroll of Bewitchment', '幻惑之卷物', '幻惑の巻物', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备的1只怪兽的属性，变成自己选择的属性。'),
(12152769, 'Scrounging Goblin', '强求哥布林', 'おねだりゴブリン', 'Effect Monster', 'Fiend', 'EARTH', 4, 1000, 2000, '①：这张卡给与对方战斗伤害的场合发动。对方可以把1张手卡交给这张卡的控制者让这个效果无效。没交的场合，自己从卡组把1张「哥布林」卡加入手卡。'),
(79205581, 'Scrubbed Raid', '强制终了', '強制終了', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '可以把自己场上存在的这张卡以外的1张卡送去墓地，这个回合的战斗阶段结束。这个效果在战斗阶段时才能发动。'),
(20920083, 'Scrum Force', '并列之力', 'スクラム・フォース', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上有表侧守备表示怪兽2只以上存在的场合，自己场上的守备表示怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ②：这张卡被效果破坏的场合，可以作为代替把其他的自己的魔法与陷阱区域1张卡破坏。'),
(56161953, 'Scrypton', '脚本加密人', 'スクリプトン', 'Effect Monster', 'Cyberse', 'WATER', 5, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把「隐藏脚本氪灯人」以外的1只电子界族怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为电子界族连接怪兽的连接素材送去墓地的场合，以除外的1只自己或者对方的怪兽为对象才能发动。那只怪兽回到持有者卡组。'),
(53309998, 'Sea Archiver', '存档海马', 'シーアーカイバー', 'Effect Monster', 'Cyberse', 'WATER', 3, 300, 2100, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，场上的连接怪兽所连接区有怪兽召唤·特殊召唤的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(76891401, 'Sea Dragon Lord Gishilnodon', '神海龙 基希尔诺顿', '神海竜ギシルノドン', 'Synchro Monster', 'Sea Serpent', 'WATER', 5, 2300, 1800, '调整＋调整以外的3星怪兽1只 场上表侧表示存在的3星以下的怪兽被送去墓地时，这张卡的攻击力直到这个回合的结束阶段时变成3000。'),
(82114013, 'Sea Dragoons of Draconia', '多拉科尼亚的海龙骑兵', 'ドラコニアの海竜騎兵', 'Pendulum Normal Monster', 'Sea Serpent', 'WATER', 3, 200, 2100, '龙人族国家德拉科尼亚帝国所拥有的龙骑士团海兵部队。擅长从深海里无声无息地偷偷靠近的隐秘作战。跟对岸的迪隆公国兵之间处于围绕领海不断发生小冲突的状态。'),
(71746462, 'Sea Kamen', '深海切割手', 'シーカーメン', 'Normal Monster', 'Aqua', 'WATER', 4, 1100, 1300, '以锐利的钩爪撕裂对方的残忍怪兽。'),
(23659124, 'Sea King Dragon', '海之龙王', '海の竜王', 'Normal Monster', 'Sea Serpent', 'WATER', 6, 2000, 1700, '海之王。长有坚硬的贝壳，从口中吐出水泡攻击。'),
(87685879, 'Sea Koala', '考拉考', 'コアラッコ', 'Effect Monster', 'Beast', 'EARTH', 2, 100, 1600, '这张卡以外的兽族怪兽在自己场上表侧表示存在的场合，可以把对方场上表侧表示存在的1只怪兽的攻击力直到结束阶段时变成0。这个效果1回合只能使用1次。'),
(22842214, 'Sea Lancer', '海洋枪兵', 'シー・ランサー', 'Effect Monster', 'Beast-Warrior', 'WATER', 5, 1300, 1000, '可以选择从游戏中除外的自己的鱼族·海龙族·水族怪兽任意数量当作装备卡使用给这张卡装备。这个效果只在这张卡在场上表侧表示存在能使用1次。这个效果把怪兽装备的场合，这张卡的攻击力上升1000。此外，场上的这张卡被破坏的场合，可以作为代替把这张卡的效果装备的1只怪兽破坏。'),
(61258740, 'Sea Lord''s Amulet', '水神的护符', '水神の護符', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己场上的水属性怪兽不会被对方的卡的效果破坏。发动后第3次的对方的结束阶段时这张卡送去墓地。'),
(96334243, 'Sea Monster of Theseus', '忒修斯的魔栖物', 'テセウスの魔棲物', 'Fusion Monster', 'Zombie', 'WATER', 5, 2200, 1800, '调整×2'),
(42071342, 'Sea Serpent Warrior of Darkness', '暗黑之海龙兵', '暗黒の海竜兵', 'Normal Monster', 'Sea Serpent', 'WATER', 4, 1800, 1500, '守护暗黑之海的战士。在水中的战斗力就不用多说了，即使是在陆地上也同时拥有很高的战斗能力。'),
(19089195, 'Sea Stealth Attack', '潜海奇袭', '潜海奇襲', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从自己的手卡·墓地选1张「海」发动。 ②：场上有「海」存在的场合，表侧表示的这张卡得到以下效果。 ●1回合1次，把自己场上1只表侧表示的水属性怪兽直到结束阶段除外才能发动。这个回合，自己场上的表侧表示的魔法·陷阱卡不会被对方的效果破坏。 ●原本等级是5星以上的自己的水属性怪兽和对方怪兽进行战斗的伤害步骤开始时发动。那只对方怪兽破坏。'),
(58203736, 'Sea Stealth II', '潜海奇袭II', '潜海奇襲Ⅱ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「海」使用。 ②：自己场上的水属性怪兽不会成为水属性以外的对方怪兽的效果的对象。 ③：自己·对方的战斗阶段开始时才能发动。从自己的手卡·墓地选1只有「海」的卡名记述的怪兽或者水属性通常怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在那次战斗阶段结束时破坏。'),
(97809599, 'Seal of the Ancients', '旧神之印', '旧神の印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付1000基本分才能发动。对方场上盖放的卡全部确认。'),
(17874674, 'Seal of Wickedness', '破邪之刻印', '破邪の刻印', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的准备阶段时只有1次，选择场上表侧表示存在的1张卡。选择的卡的效果在那个回合中无效。这张卡的控制者在每次自己的准备阶段支付500基本分。或者不支付500基本分让这张卡破坏。'),
(20345391, 'Seal, Strategist Fur Hire', '空牙团的参谋 西尔', '空牙団の参謀 シール', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的参谋 西尔」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合，以自己墓地1只「空牙团」怪兽为对象才能发动。那只怪兽加入手卡。'),
(52971944, 'Sealing Ceremony of Katon', '火遁封印式', '火遁封印式', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以把自己墓地1只炎属性怪兽从游戏中除外，选择对方墓地1张卡从游戏中除外。'),
(1802450, 'Sealing Ceremony of Mokuton', '木遁封印式', '木遁封印式', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以把自己场上表侧表示存在的1只地属性怪兽解放，选择对方墓地存在的最多2张卡从游戏中除外。'),
(42425831, 'Sealing Ceremony of Raiton', '雷遁封印式', '雷遁封印式', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以让自己场上表侧表示存在的1只风属性怪兽回到卡组最下面，选择对方墓地最多2张卡从游戏中除外。'),
(81443745, 'Sealing Ceremony of Suiton', '水遁封印式', '水遁封印式', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以把手卡1只水属性怪兽送去墓地，选择对方墓地存在的1张卡从游戏中除外。'),
(2468169, 'Sealmaster Meisei', '封印师 明晴', '封印師 メイセイ', 'Normal Monster', 'Spellcaster', 'DARK', 3, 1100, 900, '少数会使用封印符咒的人物。其来历至今还都是个谜团。'),
(80885324, 'Search Striker', '突击搜查官', 'サーチ・ストライカー', 'Effect Monster', 'Warrior', 'WIND', 4, 1600, 1200, '这张卡向里侧守备表示怪兽攻击的场合，可以不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。这个效果发动的场合，这张卡在战斗阶段结束时变成守备表示，直到下次的自己回合的结束阶段时不能把表示形式改变。'),
(67646312, 'Searchlightman', '探照灯人', 'サーチライトメン', 'Flip Effect Monster', 'Machine', 'LIGHT', 3, 1000, 1000, '反转：这个回合对方玩家不能在场上把卡盖放。'),
(47658964, 'Searing Fire Wall', '红莲之炎壁', '紅蓮の炎壁', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己墓地存在的名字带有「熔岩」的怪兽任意数量从游戏中除外发动。为这张卡发动而除外的怪兽数量的「熔岩衍生物」（炎族·炎·1星·攻/守0）在自己场上守备表示特殊召唤。'),
(22537443, 'Sebek''s Blessing', '塞贝克的祝福', 'セベクの祝福', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己怪兽直接攻击给与对方战斗伤害时才能发动。自己基本分回复那个数值。'),
(88032368, 'Second Booster', '二次推进士', 'セカンド・ブースター', 'Effect Monster', 'Machine', 'FIRE', 3, 1000, 500, '把这张卡解放，选择自己场上表侧攻击表示存在的1只怪兽发动。选择的怪兽的攻击力直到结束阶段时上升1500。'),
(36562627, 'Second Coin Toss', '第二次机会', 'セカンド・チャンス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能适用1次。 ①：自己进行投掷硬币的效果适用之际，可以从最初开始重新投掷硬币。'),
(52534264, 'Second Expedition into Danger!', '第贰次未界域探险队', '第弐次未界域探険隊', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡，以自己场上1只「未界域」怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升500。 ②：这张卡在墓地存在的场合，从手卡丢弃1只「未界域」怪兽才能发动。这张卡回到卡组最下面。那之后，自己从卡组抽1张。'),
(19086954, 'Second Goblin', '助手哥布林', 'セコンド・ゴブリン', 'Union Effect Monster', 'Fiend', 'DARK', 1, 100, 100, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「巨大兽人」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的表示形式1回合只有1次可以变更。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(27053506, 'Secret Barrel', '内置式机枪', '仕込みマシンガン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方为对方的手卡·场上的卡数量×200伤害。'),
(18252559, 'Secret Blast', '内置式爆弹', '仕込み爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方为对方场上的卡数量×300伤害。 ②：场上的这张卡被对方破坏送去墓地的场合发动。给与对方1000伤害。'),
(27527047, 'Secret Guards of the Ice Barrier', '冰结界的御庭番', '氷結界の御庭番', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 1600, '①：只要这张卡在怪兽区域存在，对方不能把自己场上的「冰结界」怪兽作为怪兽的效果的对象。'),
(77876207, 'Secret Pass to the Treasures', '通向财宝的隐藏通路', '財宝への隠し通路', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上的1只表侧表示存在的攻击力1000以下的怪兽。这个回合，选择的怪兽可以直接攻击对方玩家。'),
(61976639, 'Secret Password', '秘密验证语', 'シークレット・パスフレーズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「直播☆双子」魔法·陷阱卡或「邪恶★双子」魔法·陷阱卡加入手卡。自己场上有「姬丝基勒」怪兽以及「璃拉」怪兽存在的场合，也能作为代替把1只「邪恶★双子」怪兽加入手卡。'),
(25407643, 'Secret Sanctuary of the Spellcasters', '魔法族的圣域', '魔法族の聖域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡以外的魔法卡只有自己场上才有表侧表示存在的场合，魔法师族以外的怪兽在对方场上召唤·特殊召唤时，那个回合那些怪兽不能攻击，也不能作效果的发动。此外，自己场上没有魔法师族怪兽存在的场合，这张卡破坏。'),
(24062258, 'Secret Sect Druid Dru', '暗跃的德鲁伊·橡木', '暗躍のドルイド・ドリュース', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, NULL, '这张卡召唤成功时，可以从自己墓地选择「暗跃的德鲁伊·橡木」以外的1只攻击力或者守备力是0的暗属性·4星怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「暗跃的德鲁伊·橡木」的效果1回合只能使用1次。'),
(97064649, 'Secret Sect Druid Wid', '暗跃的德鲁伊·智者', '暗躍のドルイド・ウィド', 'Effect Monster', 'Spellcaster', 'DARK', 4, NULL, 1800, '这张卡从场上送去墓地的场合，可以选择自己墓地1张永续魔法卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。「暗跃的德鲁伊·智者」的效果1回合只能使用1次。'),
(70180284, 'Secret Six Samurai - Doji', '影六武众－道顺', '影六武衆－ドウジ', 'Effect Monster', 'Warrior', 'DARK', 4, 1700, 1200, '①：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「六武众」怪兽召唤·特殊召唤时才能发动。从卡组把1张「六武众」卡送去墓地。 ②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(71207871, 'Secret Six Samurai - Fuma', '影六武众－风魔', '影六武衆－フウマ', 'Tuner Monster', 'Warrior', 'WIND', 1, 200, 1800, '①：这张卡被战斗·效果破坏的场合才能发动。从卡组把「影六武众-风魔」以外的1只「六武众」怪兽特殊召唤。 ②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(7291576, 'Secret Six Samurai - Genba', '影六武众－玄蕃', '影六武衆－ゲンバ', 'Tuner Monster', 'Warrior', 'FIRE', 2, 500, 2100, '①：这张卡召唤成功时，以除外的1只自己的「六武众」怪兽为对象才能发动。那只怪兽加入手卡。 ②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(44686185, 'Secret Six Samurai - Hatsume', '影六武众－初芽', '影六武衆－ハツメ', 'Effect Monster', 'Warrior', 'WATER', 3, 1600, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：从自己墓地以及自己场上的表侧表示怪兽之中把2只「六武众」怪兽除外，以「影六武众-初芽」以外的自己墓地1只「六武众」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(6579928, 'Secret Six Samurai - Kizaru', '影六武众－鬼猿', '影六武衆－キザル', 'Effect Monster', 'Warrior', 'EARTH', 4, 1900, 1000, '①：这张卡特殊召唤成功时才能发动。自己场上存在的属性以外的1只「六武众」怪兽从卡组加入手卡。 ②：只让自己场上的「六武众」怪兽1只被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(33964637, 'Secret Six Samurai - Rihan', '影六武众－里半', '影六武衆－リハン', 'Fusion Monster', 'Warrior', 'LIGHT', 5, 2400, 2400, '属性不同的「六武众」怪兽×3 把自己场上的上记卡送去墓地的场合才能从额外卡组特殊召唤（不需要「融合」）。这张卡不能作为融合素材。 ①：1回合1次，从手卡以及自己场上的表侧表示的卡之中把1张「六武众」卡除外，以场上1张卡为对象才能发动。那张卡除外。 ②：自己场上的「六武众」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(79968632, 'Secret Skills of the Six Samurai', '六武众之影忍术', '六武衆の影忍術', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只怪兽送去墓地，以除外的1只自己的「六武众」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(42081767, 'Secret Stash Slipshod Squirrel', '隐藏坚果的粗心松鼠', 'きのみ隠しのうっかりす', 'Effect Monster', 'Beast', 'EARTH', 1, 200, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以自己墓地最多3张魔法·陷阱卡为对象才能发动。那些卡除外。下个回合的结束阶段，这个效果除外的卡回到卡组。 ②：自己准备阶段，以自己的除外状态的1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(68462976, 'Secret Village of the Spellcasters', '魔法族之乡', '魔法族の里', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只有自己场上才有魔法师族怪兽存在的场合，对方不能把魔法卡发动。 ②：自己场上没有魔法师族怪兽存在的场合，自己不能把魔法卡发动。'),
(89851827, 'Secreterion Dragon', '圣秘龙骑士', '聖秘なる竜騎士', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 3000, 1500, '龙族怪兽＋魔法师族怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力下降自己的除外状态的卡数量×100。 ②：只要融合召唤的这张卡在怪兽区域存在，对方场上的特殊召唤的龙族·魔法师族怪兽不能把效果发动。 ③：以自己墓地的龙族和魔法师族的怪兽各1只为对象才能发动。那之内的1只特殊召唤，另1只回到卡组最下面。'),
(59514116, 'Secrets of Dark Magic', '黑魔术之秘仪', '黒魔術の秘儀', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●包含「黑魔术师」或「黑魔术少女」的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含「黑魔术师」或「黑魔术少女」的自己的手卡·场上的怪兽解放，从手卡把1只仪式怪兽仪式召唤。'),
(95096437, 'Secrets of the Gallant', '义贼的极意书', '義賊の極意書', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只通常怪兽发动。这个回合选择怪兽给与对方基本分战斗伤害时，对方随机丢弃2张手卡。'),
(15507080, 'Sectarian of Secrets', '黑暗随从者', '闇にしたがう者', 'Normal Monster', 'Spellcaster', 'DARK', 2, 700, 500, '崇拜黑暗的魔法师。呼唤魔手将敌人拖入暗阴之中。'),
(2220237, 'Secure Gardna', '安全守卫', 'セキュア・ガードナー', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1000, NULL, '电子界族连接怪兽1只 这张卡不能作为连接素材。 ①：「安全守卫者」在自己场上只能有1只表侧表示存在。 ②：这张卡特殊召唤成功的回合，自己受到的效果伤害变成0。 ③：自己因战斗·效果受到伤害的场合，1回合只有1次让那次伤害变成0。'),
(91665064, 'Security Block', '安全屏蔽', 'セキュリティ・ブロック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只电子界族怪兽为对象才能发动。这个回合，那只怪兽不会被战斗破坏，双方受到的全部战斗伤害变成0。'),
(99111753, 'Security Dragon', '安全龙', 'セキュリティ・ドラゴン', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1100, NULL, '怪兽2只 这个卡名的效果1回合只能使用1次。 ①：只在这张卡在场上表侧表示存在才有1次，这张卡是互相连接状态的场合以对方场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。'),
(26533075, 'Security Orb', '保安球', 'セキュリティー・ボール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把那1只攻击怪兽的表示形式改变。对方的魔法·陷阱卡的效果把盖放的这张卡破坏送去墓地时，选择场上存在的1只怪兽破坏。'),
(93104633, 'Security Token', '动态认证码', 'ワンタイム・パスコード', 'Token', 'Cyberse', NULL, NULL, NULL, NULL, NULL),
(81524977, 'Seed Cannon', '种子弹丸', '種子弾丸', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次植物族怪兽召唤·反转召唤·特殊召唤，给这张卡放置1个植物指示物（最多5个）。可以把场上存在的这张卡送去墓地，给与对方基本分这张卡放置的植物指示物数量×500的数值的伤害。'),
(18752938, 'Seed of Deception', '假种子', '偽りの種', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '从手卡把1只2星以下的植物族怪兽特殊召唤。'),
(38041940, 'Seed of Flame', '火焰花种', 'シード・オブ・フレイム', 'Effect Monster', 'Plant', 'FIRE', 3, 1600, 1200, '自己场上存在的这张卡被卡的效果破坏送去墓地时才能发动。自己墓地存在的「火焰花种」以外的1只4星以下的植物族怪兽在自己场上特殊召唤，在对方场上把1只「花种衍生物」（植物族·地·1星·攻/守0）守备表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(38041941, 'Seed Token', '火焰花种', 'シード・オブ・フレイム', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(35263180, 'Seed-Spitting Saplings', '偷吃零嘴的大屋枛姬', 'オオヤツ・ツマムヒメ', 'Effect Monster', 'Plant', 'LIGHT', 4, 1600, 200, '①：1回合1次，场上的这张卡成为攻击·效果的对象时才能发动。在自己场上把1只「点心衍生物」（植物族·光·1星·攻/守800）特殊召唤。 ②：1回合1次，对方把怪兽特殊召唤之际，把自己场上1只通常怪兽解放才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(15066114, 'Segmental Dragon', '分段龙', 'セグメンタル・ドラゴン', 'Effect Monster', 'Cyberse', 'LIGHT', 7, 2600, 2400, '①：这张卡可以不用解放作通常召唤。 ②：这张卡的①的方法通常召唤的这张卡的原本的攻击力·守备力变成一半。 ③：1回合1次，这张卡是已通常召唤的场合才能发动。表侧表示的这张卡破坏，持有那个攻击力以下的攻击力的主要怪兽区域的怪兽全部破坏。这个效果在对方回合也能发动。'),
(114932, 'Seismic Crasher', '板块轰击者', 'プレートクラッシャー', 'Effect Monster', 'Rock', 'EARTH', 3, 1400, 300, '把自己场上存在的1张表侧表示的永续魔法或者永续陷阱卡送去墓地。给与对方基本分500分伤害。这个效果1回合可以使用最多2次。'),
(79569173, 'Seismic Shockwave', '大地震', '大地震', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的恐龙族怪兽被破坏送去墓地时才能发动。从对方场上的魔法与陷阱卡区域指定3处。指定的魔法·陷阱卡区域不能使用。这个时候有卡存在的地方不能指定。这张卡发动后第3次的自己准备阶段时破坏。因这个效果破坏的场合，可以使自己墓地的1只恐龙族怪兽回到手卡。'),
(6740720, 'Seiyaryu', '圣夜龙', 'ホーリー・ナイト・ドラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 7, 2500, 2300, '用神圣之炎烧尽邪恶，拥有神圣之力的龙。'),
(24940422, 'Sekka''s Light', '雪花之光', '雪花の光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合才能发动。自己从卡组抽2张。这张卡的发动后，这次决斗中自己不能把「雪花之光」以外的魔法·陷阱卡的效果发动。 ②：把墓地的这张卡除外才能发动。把手卡1只怪兽给对方观看，回到卡组洗切。那之后，自己从卡组抽1张。'),
(29303524, 'Seleglare the Luminous Lunar Dragon', '眩月龙 塞勒桂莱尔', '眩月龍セレグレア', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以不用解放作通常召唤。 ②：这张卡的①的方法通常召唤的这张卡的原本攻击力变成1500。 ③：自己·对方的主要阶段，以持有这张卡的攻击力以下的攻击力的对方场上1只怪兽为对象才能发动。场上的这张卡回到手卡，作为对象的怪兽的控制权直到结束阶段得到。'),
(45819647, 'Selene, Queen of the Master Magicians', '神圣魔皇后 塞勒涅', '神聖魔皇后セレーネ', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1850, NULL, '包含魔法师族怪兽的怪兽2只以上 ①：这张卡连接召唤的场合发动。双方的场上·墓地的魔法卡数量的魔力指示物给这张卡放置。 ②：只要场上有「恩底弥翁」卡存在，对方怪兽不能选择这张卡作为攻击对象。 ③：1回合1次，自己·对方的主要阶段，把自己场上3个魔力指示物取除才能发动。从自己的手卡·墓地选1只魔法师族怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。'),
(23093373, 'Selettrice Vaalmonica', '天魔之声选姬・华耳琴璃', '天魔の聲選姫', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1200, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·灵摆召唤的场合才能发动。从卡组把「天魔之声选姬」以外的1张「异响鸣」卡加入手卡。 ②：只要自己场上有「天魔之声选姬」以外的怪兽存在，对方怪兽不能选择这张卡作为攻击对象。 ③：这张卡被送去墓地的场合，若自己的灵摆区域有2张「异响鸣」卡存在则能发动。这张卡加入手卡。'),
(6783559, 'Self-Destruct Ant', '自爆蚁', 'アリジバク', 'Flip Effect Monster', 'Insect', 'EARTH', 3, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合发动。双方玩家受到1000伤害。 ②：这张卡被战斗·效果破坏送去墓地的场合发动。给与对方1000伤害。'),
(57585212, 'Self-Destruct Button', '自爆开关', '自爆スイッチ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的基本分比对方少7000以上时这张卡才能发动。双方的基本分全都变成0。'),
(15103313, 'Self-Mummification', '即神佛', '即神仏', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上存在的1只怪兽送去墓地。');